window.PIAIcons = {
  svg(name, cls){
    const d = window.PIA_ICONS[name]; if(!d) return '';
    return '<svg class="ico'+(cls?' '+cls:'')+'" viewBox="'+d.vb+'" fill="none" aria-hidden="true" focusable="false" style="width:1em;height:1em;display:inline-block;vertical-align:-0.125em">'+d.inner+'</svg>';
  },
  render:function(root){
    var D=window.PIA_ICONS;
    (root||document).querySelectorAll('[data-ico],[class*="ico-"]').forEach(function(el){
      if(el.tagName==='svg')return;
      var n=el.getAttribute('data-ico');
      if(!n){ (el.className.baseVal||el.className||'').split(/\s+/).forEach(function(c){ var m=/^ico-(.+)$/.exec(c); if(m&&D[m[1]])n=m[1]; }); }
      if(!n||!D[n])return;
      var d=D[n];
      var s=document.createElementNS('http://www.w3.org/2000/svg','svg');
      s.setAttribute('viewBox',d.vb); s.setAttribute('fill','none'); s.setAttribute('aria-hidden','true');
      (el.getAttribute('class')||'').split(/\s+/).forEach(function(c){c&&s.classList.add(c);});
      if(!s.classList.contains('ico'))s.classList.add('ico');
      s.innerHTML=d.inner;
      if(el.getAttribute('style'))s.setAttribute('style',el.getAttribute('style'));
      el.replaceWith(s);
    });
  }
};
document.addEventListener('DOMContentLoaded', function(){ window.PIAIcons.render(); });
